{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)
    if budget < sum_min or budget > sum_cap:
        return {'error': 'Budget out of range'}
    alloc = {s['name']: s['minimum'] for s in segments}
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, s in enumerate(segments):
            name = s['name']
            next_pos = alloc[name] + 1
            if next_pos > s['capacity']:
                continue
            ratio = s['importance'] / next_pos
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx == -1:
            break
        name_alloc = segments[best_idx]['name']
        alloc[name_alloc] += 1
        remaining -= 1
    return {
        'allocations': alloc,
        'names': [s['name'] for s in segments],
        'total_allocated': sum(alloc.values())
    }"}
